(13658, NULL, 'LXII', '2016-03-01', '2016-03-01', 'Ordinaria', 'correspondencia especial', NULL, '2016-02-29', NULL, 0, ' ENRI PACHECO JESUS', 'SECRETARIO DEL JUZGADO PRIMERO', 'PODER JUDICIAL DE LA FEDERACION', NULL, NULL, 'user', NULL, 'EN RELACION AL JUICIO DE AMPARO 1699/2015 PROMOVIDO POR LETICIA LOPEZ DOMINGUEZ SE COMUNICA SENTENCIA.\nENVIA ANEXO.', NULL, 'LIC. JOSE LUIS BALAM CHANONA', 'DIRECTOR DE PROCESOS LEGISLATI', 'CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2016-03-02 06:09:06', '2016-03-02 02:06:48'),
(13659, NULL, 'LXII', '2016-03-01', '2016-03-01', 'Ordinaria', 'correspondencia especial', NULL, '2016-02-25', NULL, 1, ' CAMARA DE SENADORES', NULL, NULL, NULL, NULL, 'user', NULL, 'SE APROBARON DICTAMEN CON PUNTO DE ACUERDO: SE EXHORTA A LOS CONGRESOS, AL TITULAR DEL PODER EJECUTIVO REVISEN LA EFICACIA DE MECANISMOS CONVENCIONALES DE LA ADMINISTRACION Y APLICACION DE RECURSOS FINANCIEROS DESTINADOS A LAS MENCIONADAS INSTITUCIONES. SE EXHORTA AL GOBERNADOR DE VERACRUZ ACATE LOS TERMINOS DISPUESTOS POR EL CONVENIO DE APOYO FINANCIERO PARA EJERCICIO 2015 SUSCRITO POR SRIA EDUC DE VERACRUZ. SE EXHORTA A LA CORRECTA APLICACION DE RECURSOS EN LA UNIVERSIDAD DE VERACRUZ.Y A AUDITAR LA ADMINISTRACION Y APLICACION DE RECURSOS EN A UNIV VERACRUZANA. FIRMA SN. ROSA ADRIANA DIAZ LIZAMA', NULL, 'ING. SONIA ALEJANDRA CASTILLO PERALTA', 'OFICINA DE LA SRIA GRAL', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2016-03-02 02:38:24', '2016-03-02 02:56:54'),
