(32896, NULL, 'LXIV', '2022-12-09', '2022-12-09', 'Ordinaria', 'correspondencia especial', NULL, '2022-12-09', NULL, NULL, 'L.C. JOSE JAIME PARRES MORENO', 'DIRECTOR DE SERVICIOS ADMINIST', 'H. CONGRESO DEL ESTADO.', NULL, NULL, 'user', NULL, 'OFICIO PLE/SG/DSA/RH/1369\nENVIA EN SOBRE CERRADO RECIBOS DE PAGO DEL PERSONAL ADSCRITO A SU DIRECCION CORRESPONDIENTE A LA GRATIFCACION ANUAL DEL AÑO EN CURSO, QUE DEBERAN SER REMITIDOS DEBIDAMENTE FIRMADOS EN SOBRE CERRADO A LOS 3 DÍAS HÁBILES SIGUIENTES A LA QUINCENA.', NULL, 'LIC. BLANCA LUZ CALDERON LOPEZ', 'DIRECTORA', 'JUNTA DE GOBIERNO Y ADMINISTRACION', NULL, NULL, NULL, 0, '2022-12-10 03:56:27', '2022-12-10 04:14:02'),
(32897, NULL, 'LXIV', '2022-12-09', '2022-12-09', 'Ordinaria', 'Correspondencia normal', 'Informes', '2022-12-08', NULL, 71, 'LIC. FERNANDO PULIDO ARA', 'TESORERO MUNICIPAL', 'H. AYUNTAMIENTO CALAKMUL', NULL, NULL, 'user', 'CALLE HALALTUN S/N, COL. CENTRO C.P. 24640\nXPUJIL, CALAKMUL, CMPECHE.', 'EL H. AYUNTAMIENTO DE CALAKMUL ENVIA EL INFORME CORRESPONDIENTE AL TERCER TRIMESTRE 2021, REFERENTE A LA INFORMACION FINANCIERA Y DE OBLIGACIONES DEL TITULO V QUE ETABLECE LA LEY DE CONTABILIDAD GUBERNAMENTAL:\nINFORME CONTABLE, INFORMACION PRESUPUESTARIA, INFORMACION PROGRAMATICA, FORMATOS DE TRANSPARENCIA DEL TITULO V DDE LA LGCG  E INFORMACION RELATIVA A LA LEY DE DISCIPLINA FINANCIERA.\nENVIA ENGARGOLADO.', 'OFICIO DIRIGIDO AL DIP. ALEJANDRO GOMEZ CAZARIN.', 'LIC. RAMON GONZALEZ FLORES', 'SECRETARIA GENERAL', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2022-12-10 05:45:01', '2022-12-10 04:14:40'),
