(32964, NULL, 'LXIV', '2023-01-04', '2023-01-04', 'Ordinaria', 'Correspondencia normal', 'Informes', '2022-12-07', NULL, 6, ' H. CONGRESO DE QUINTANA ROO', NULL, NULL, NULL, NULL, 'user', 'CALLE ESMERALDA NÂ° 102, ENTRE MIGUEL HIDALGO Y BOULEVARD BAHIA, COL. BARRIO BRAVO, C.P. 77098, CHETUMAL, QUINTANA ROO', 'OFICIO DIRIGIDO A LA PRESIDENCIA DE LA MESA DIRECTIVA DEL H. CONGRESO DEL ESTADO DE CAMPECHE.\nCOMUNICA PUNTO DE ACUERDO RELACIONADO CON LAS ACCIONES LEGALES QUE BUSCAN FRENAR EL TRAFICO ILEGAL DE ARMAS HACIA MEXICO Y CON ELLO PONER UN ALTO AL CRIMEN ORGANIZADO PARA LOGRAR LA CONSTRUCCION DE LA PAZ EN EL PAIS.\nFIRMAN OFICIO LAS DIPUTADAS PROFR. MILDRED CONCEPCION AVILA VERA Y CRISTINA DEL CARMEN ALCÉRRECA MANZANERO.', NULL, 'ING. SONIA ALEJANDRA CASTILLO PERALTA', 'OFICINA DE LA SRIA GRAL', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-01-05 06:14:17', '2023-01-05 08:20:32'),
(32965, NULL, 'LXIV', '2023-01-04', '2023-01-04', 'Ordinaria', 'Correspondencia normal', 'Informes', '2022-12-05', '1', 1, ' H. CONGRESO DE MORELOS', NULL, NULL, NULL, NULL, 'user', NULL, 'OFICIO DIRIGIDO AL CONGRESO DEL ESTADO DE CAMPECHE.\nCOMUNICA ADICION DE UNA FRACCION X AL ARTICULO 116 DE LA CONSTITUCION POLITICA DE LOS ESTADOS UNIDOS UNIDOS MEXICANOS, EN MATERIA DE SIMBOLOS DE LAS ENTIDADES FEDERATIVAS.\nFIRMA: LIC. CESAR FRANCISCO BETANCOURT LOPEZ, SECRETARIO DE SERVICIOS LEGISLATIVOS Y PARLAMENTARIOS DEL CONGRESO DEL ESTADO DE MORELOS.', NULL, 'ING. SONIA ALEJANDRA CASTILLO PERALTA', 'OFICINA DE LA SRIA GRAL', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-01-05 02:51:11', '2023-01-05 04:47:03'),
