(33150, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'Correspondencia normal', 'Informes', '2023-01-25', NULL, 1, 'ING. EDUARDO JUAN GUERRERO VALDÉZ', 'DIRECTOR GENERAL', 'SECRETARIA DE INFRAESTRUCTURA, COMUNICACIONES Y TRANSPORTES.', NULL, NULL, 'user', 'AVENIDA LAS PALMAS S/N, COL. ESTACION ANTIGUA, C.P. 24020\nSAN FRANCISCO DE CAMPECHE, CAMPECHE.', 'OFICIO DIRIGIDO TAMBIÉN A LOS DIPUTADOS: CÉSAR ANDRÉS GONZÁLEZ DAVID, JOSÉ HÉCTOR MALAVÉ, JOSÉ ANTONIO JIMÉNEZ GUTIÉRREZ.     ENVIA RESPUESTA SU OFICIO 001/2023 DE FECHA 12 DE ENERO EN EL QUE MANIFIESTAN SU INTERÉS DE \"RECUPERAR LAS VIAS FERROVIARIAS QUE ATRAVIESAN LA CIUDAD DE CAMPECHE DESDE LA LOCALIDAD DE LERMA HASTA IMÍ.\nINFORMA QUE DICHA VIA CORRESPONDIENTE A LA LINEA FL CAMPECHE-LERMA FUÉ ASIGNADA A LA EMPRESA FERROCARRIL DEL ISTMO DE TEHUANTEPEC S.A. DE C.V. MEDIANTE EL TÍTULO DE CONCESION DE FECHA 23 DE DICIEMBRE DE 1999 Y SU MODIFICACION DE FECHA 20  DE DICIEMBRE 2017, ACTUALMENTE SE ENCUENTRAN SIN USO ALGUNO.\nASIMISMO MENCIONA QUE SE INFORMARÁ DE SU SOLICITUD A LA DIRECCION GENERAL DE TRANSPORTE FERROVIARIO Y MULTIMODAL ASÍ COMO DEL ESTADO QUE GUARDA A EFECTO DE QUE SE EMITA LA OPINION RESPECTIVA.', NULL, 'DIP ELISA MARIA HERNÁNDEZ ROMERO', 'PLURINOMINAL MORENA', NULL, NULL, NULL, NULL, 0, '2023-01-28 04:39:30', '2023-01-28 06:32:09'),
(33151, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'Correspondencia normal', 'Informes', '2022-09-08', NULL, 1, ' FRANCISCO INOCENTE VALES GONZÁLEZ', 'DIRECTOR GENERAL DE TRANSPORTE', 'SEDUC - CAMPECHE', NULL, NULL, 'user', 'AV. MAESTROS CAMPECHANOS S/N, SAN FRANCISCO DE CAMPECHE, CAMP. 24095\nCAMPECHE, CAMP.', 'ENVIA COPIA DE OFICIO TURNADO A LA C. ROSA ISELA RAMÍREZ ORTEGA, REPRESENTANTE DE PADRES DE FAMILIA DE LAS LOCALIDADES DE \"18 DE MARZO Y SAN ISIDRO\" EN EL QUE DA RESPUESTA A SOLICITUD RELATIVA A APOYO DE TRASLADO DE ALUMNOS QUE VIVEN EN LAS COMUNIDADES DE 18 DE MARZO, SAN ISIDRO Y SUS ALREDEDORES PARA TRASLADARLOS AL COBACAM PLANTEL 06, UBICADO EN LA LOCALIDAD DE \"FRANCISCO VILLA \"MAMANTEL\"  PERTENECIENTE AL MUNICIPIO DE CARMEN, AL RESPECTO INFORMA QUE SE VEN IMPOSIBILITADOS PARA PROPORCIONARLE UNA RESPUESTA POSITIVA POR EL MOMENTO YA QUE EL PRESUPUESTO ANUAL OTORGADO PARA EL  EJERCICIO FISCAL 2022, SE ENCUENTRA EN USO EN RUTAS ESTABLECIDAS, EN CASO DE QUE SE AMPLIÉ EL TECHO PRESUPUESTAL SE LE INFORMARÁ ACERCA DEL PROYECTO.', NULL, 'DIP GENOVEVA MORALES FUENTES', 'DIPUTADA PLURINOMINAL MORENA', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-01-28 05:35:05', '2023-01-28 03:17:33'),
(33152, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'Peticiones', 'Peticiones para gestión', '2023-01-27', NULL, 2, ' FLOR DE MARIA NAR REQUENA', NULL, NULL, NULL, NULL, 'user', 'calle kala° 33, inf. kala c.p. 24085, campeche, camp', 'SOLICITA APOYO PORQUE TIENE LA NECESIDAD DE REALIZAR TRÁMITES COMO ACTA DE NACIMIENTO Y FOTOGRAFÍAS Y NO CUENTA CON EL DINERO.', NULL, 'LIC EUNICE ARELY LOMELIN ESTRADA', 'DIRECTORA DE GESTION SOCIAL', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-01-28 03:32:19', '2023-01-28 03:23:31'),
(33153, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'Correspondencia normal', 'Informes', '2022-12-15', NULL, 1, ' H CONGRESO DE YUCATAN', NULL, NULL, NULL, NULL, 'user', NULL, 'OFICIO DIRIGIDO AL H. CONGRESO DEL ESTADO DE CAMPECHE.\nCOMUNICA PUNTO DE ACUERDO DE FECHA 19 DE OCTUBRE DEL AÑO 2022. QUE A LA LETRA DICE: \"CON ABSOLUTO RESPETO A LA DIVISION DE PODERES, SE EXHORTA A LAS Y LOS INTEGRANTES DE LA CAMARA DE SENADORES, CAMARAS DE DIPUTADOS Y A LOS CONGRESOS ESTATALES DE TODAS LAS ENTIDADES FEDERATIVAS, A QUE MANIFIESTEN SU RESPALDO A LAS ACCIONES LEGALES EMPRENDIDAS POR EL GOBIERNO DE MÉXICO Y CON ELLO PONER UN ALTO AL CRIMEN ORGANOIZADO PARA LOGRAR LA CONSTRUCCIÓN DE LA PAZ EN EL PAÍS.\nFIRMA DIP. RAFAEL ALEJANDRO ECHAZARRETA TORRES, SECRETARIO DE  LA MESA DIRECTIVA.', NULL, 'ING. SONIA ALEJANDRA CASTILLO PERALTA', 'OFICINA DE LA SRIA GRAL', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-01-28 03:19:52', '2023-01-28 06:46:58'),
(33154, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2022-11-08', NULL, 4, ' JUZGADO PRIMERO DE DISTRITO DE CENTRO AUXILIAR DE LA 1RA. REGION', 'CIUDAD DE MEXICO.', NULL, NULL, NULL, 'user', NULL, 'EJECUTORIA.\nJUICIO DE AMPARO: 3560/2019     PROMOVENTE: CARLOS ALBERTO SOSA LÓPEZ.  \nVISTO EL ESTADO PROCESAL DE AUTOS Y LA SEGUNDA CERTIFICACIÓN DE CUENTA, SE ADVIERTE QUE TRANSCURRIÓ EL PLAZO PREVISTO EN EL ARTICULO 86 DE LA LEY DE AMPARO, SIN QUE A LA FECHA SE INTERPUSIERA RECURSO DE REVISION EN CONTRA DE LA SENTENCIA DICTADA EL VEINTIDOS DE MARZO DE DOS MIL VEINTIDOS EN LA CUAL SE DETERMINÓ SOBRESEER EL PRESENTE JUICIO DE AMPARO.\nPOR LO TANTO SE DECLARA QUE LA REFERIDA RESOLUCIÓN HA CAUSADO EJECUTORIA PARA TODOS LOS EFECTOS LEGALES CONDUCENTES.\nFIRMA OFICIO: JUANA ADRIANA GARCÍA LARA, SECRETARIA DEL JUZGADO.', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-28 07:27:21', '2023-01-28 06:11:03'),
(33155, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-01-23', NULL, 3, ' JUZGADO DECIMOTERCERO DE DISTRITO, ESTADO DE MEXICO NAUCALPAN DE JUAR', NULL, NULL, NULL, NULL, 'user', NULL, 'ACUERDO.\nJUICIO DE AMPARO: 453/2022-C-4  PROMOVIDO POR NUEVA ELEKTRA DEL MILENIO S.A. DE C.V.\nDE CONFORMIDAD CON EL ARTÍCULO 192 DE LA LEY DE AMPARO SE REQUIERE AL GOBERNADOR Y CONGRESO CONSTITUCIONAL, AMBOS DEL ESTADO DE CAMPECHE, PARA QUE DENTRO DEL TÉRMINO DE TRES DÍAS LEGALMENTE COMPUTADO, DEN CUMPLIMIENTO A LA SENTENCIA DE NUEVE DE DICIEMBRE DEL AÑO EN CURSO.\nFIRMA OFICIO: EDUARDO HERNANDEZ MONTIEL, SECRETARIO. \n', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-28 05:42:14', '2023-01-28 04:07:08'),
(33156, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2022-11-08', '91249', 9, ' JUZGADO PRIMERO DE DISTRITO DE CENTRO AUXILIAR DE LA 1RA. REGION', 'CIUDAD DE MEXICO.', NULL, NULL, NULL, 'user', NULL, 'ACUERDO.\nJUICIO DE AMPARO 3140/2019    PROMOVENTE: JUAN CARLOS ORTEGON D ELA FUENTE.\nSE RESOLVIÓ LO SIGUIENTE: \"UNICO.- SE DECLARA SIN MATERIA EL PRESENTE RECURSO DE QUEJA INTERPUESTO\".\nFIRMA OFICIO: JUANA ADRIANA GARCÍA LARA, SECRETARIA.', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-28 02:03:21', '2023-01-28 05:34:05'),
(33157, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2022-11-24', '98778', 10, ' JUZGADO PRIMERO DE DISTRITO DE CENTRO AUXILIAR DE LA 1RA. REGION', 'CIUDAD DE MEXICO.', NULL, NULL, NULL, 'user', NULL, 'ACUERDO.\nJUICIO DE AMPARO 461/2021    PROMOVENTE: GABRIELA ARROYO NAVA.\n...FORMESE CUADERNO DE ANTECEDENTES ÚNICAMENTE CON COPIA DEL OFICIO DE AGRAVIOS Y COPIA AUTORIZADA DEL PRESENTE PROVEIDO; EN VIRTUD QUE, LA TOTALIDAD DE LAS CONSTANCIAS DE ESTE SUMARIO SE ENCUENTRAN DIGITALIZADAS EN EL EXPEDIENTE ELECTRÓNICO QUE SE LLEVA EN EL SISTEMA INTEGRAL DE EXPEDIENTES.\nFIRMA OFICIO: CITLALLI GONZALEZ BECERRA, SECRETARIA.\n', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-28 03:29:47', '2023-01-28 05:12:28'),
(33158, NULL, 'LXIV', '2023-01-27', '2023-01-27', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-01-27', NULL, 4, ' JUZGADO PRIMERO DE DISTRITO DE CENTRO AUXILIAR DE LA 1RA. REGION', 'CIUDAD DE MEXICO.', NULL, NULL, NULL, 'user', NULL, 'ACUERDO DERIVADO DE RECURSO DE REVISION INTERPUESTO.\nJUICIO DE AMPARO 3560/2019     PROMOVENTE. CARLOS ALBERTO SOSA LOPEZ\nSE DECLARÓ SIN MATERIA EL RECURSO DE REVISIÓN INTERPUESTO POR EL PRESIDENTE CONSTITUCIONAL DE LOS ESTADOS UNIDOS MEXICANOS, EN CONTRA DE LA RESOLUCIÓN INTERLOCUTORIA DICTADA EN AUTOS, ASIMISMO, DEVUELVE LOS AUTOS ORIGINALES DEL CUADERNO INCIDENTAL EN QUE SE ACTUA.\nFIRMA: JUANA ADRIANA GARCÍA LARA, SECRETARIA.', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-28 02:56:52', '2023-01-28 05:50:54'),
(33159, NULL, 'LXIV', '2023-01-30', '2023-01-30', 'Ordinaria', 'Correspondencia normal', 'Invitaciones', '2023-01-27', NULL, 1, 'LIC. RODOLFO ENRIQUE CARDOZO RIVERO', 'DIRECTOR GENERAL', 'INSTITUTO TECNOLOGICO SUPERIOR DE CALKINI', NULL, NULL, 'user', 'AV. AH. CANUL S/N POR CARRETERA FEDERAL, CALKINI , CAMPECHE CP. 24900', 'INVITACION AL DIPUTADO PRESIDENTE A PRESIDIR EVENTO DE VISITA AL ITESCAM UBICADO EN CALKINÍ, CAMPECHE; DEL DIRECTOR GENERAL DELTECNOLÓGICO NACIONAL DE MÉXICO, MTRO. RAMÓN JIMÉNEZ LÓPEZ, EL PRÓXIMO 1 DE FEBRERO A LAS 16:00 HRS.\nCONFIRMAR ASISTENCIA AL 9961043200 O AL CORREO ELECTRÓNICO: bgvelazquez@itescam.edu.mx.', NULL, 'DIP. ALEJANDRO GÓMEZ CAZARÍN', 'PRESIDENTE DE LA JUNTA DE GOBI', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-01-31 05:23:37', '2023-01-31 07:09:59'),
(33160, NULL, 'LXIV', '2023-01-30', '2023-01-30', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-01-27', NULL, 4, 'LIC JOSE ABELARDO RODRIGUEZ CANTU', 'SRIO DEL JUZGADO 1°  DISTRITO', 'CAMPECHE', NULL, NULL, 'user', NULL, 'SOLICITA INFORME JUSTIFICADO.\nJUICIO DE AMPARO 79/2023-II-B   PROMOVENTE: CONCEPCION PAUL GALLARETA.\nCOMUNICA ADMISION DE DEMANDA DE AMPARO, SEÑALA LAS DIEZ HORAS CON CINCO MINUTOS DEL UNO DE MARZO DE DOS MIL VEINTITRÉS, PARA QUE TENGA VERIFICATIVO LA AUDIENCIA CONSTITUCIONAL.     SOLICITA INFORME JUSTIFICADO DENTRO DEL TÉRMINO DE QUINCE DÍAS. ', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-31 03:03:20', '2023-01-31 06:41:55'),
(33161, NULL, 'LXIV', '2023-01-30', '2023-01-30', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-01-27', NULL, 34, 'LIC JOSE ABELARDO RODRIGUEZ CANTU', 'SRIO DEL JUZGADO 1°  DISTRITO', 'CAMPECHE', NULL, NULL, 'user', NULL, 'SOLICITA INFORME PREVIO.\nEXPEDIENTE: 79/2023-II-A    PROMOVENTE. CONCEPCION PAUL GALLARETA.\nSE SOLICITA INFORME PREVIO A LAS AUTORIDADES RESPONSABLES  QUE DEBERÁN RENDIR EN UN TÉRMINO DE CUARENTA Y OCHO HORAS.\nSE SEÑALAN LAS NUEVE HORAS CON VEINTICINCO MINUTOS DEL TRES DE FEBRERO DE DOS MIL VEINTITRES PARA QUE TENGA VERIFICATIVO LA AUDIENCIA INCIDENTAL.\n', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-31 07:55:25', '2023-01-31 07:47:58'),
(33162, NULL, 'LXIV', '2023-01-30', '2023-01-30', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-01-26', '3249', 2, 'LIC. EDUARDO ALCOCER DIAZ', 'SECRETARIO', 'JUZGADO SEGUNDO DE DISTRITO - CAMPECHE', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COL. SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE.', 'SE COMUNICA EJECUTORIA Y ARCHIVO.\nJUICIO DE AMPARO INDIRECTO.    PROMOVENTE: INÉS DEL CARMEN NAVARRETE PAVON.\nVISTO EL ESTADO PROCESAL QUE GUARDDAN LOS PRESENTES AUTOS Y LA CERTIFICACION QUE ANTECEDE, SE ADVIERTE QUE DENTRO DEL TÉRMINO SEÑALADO EN EL ARTÍCULO  86 DE LA LEY DE AMPARO, LA SENTENCIA DE EN LA QUE SE NEGÓ EL AMPARO Y PROTECCION DE LA JUSTICIA EN EL PRESENTE JUICIO, NO FUE RECURRIDA, POR TANTO CON  FUNDAMENTO EN EL ARTÍCULO 356,FRACCION II DEL CÓDIGO FEDERAL DE PROCEDIMEINTOS CIVILES APLICADO SUPLETORIAMENTE A LA LEY DE AMPARO CONFORME A SU ARTICULO 2°, SE DECLARA QUE HA CAUSADO EJECUTORIA. HÁGANSE LAS ANOTACIONES EN EL LIBRO DE GOBIERNO.\n\n\n', NULL, 'LIC. ORLANDO ENRIQUE RICALDE GONZALEZ', 'DIRECTOR', NULL, NULL, NULL, NULL, 0, '2023-01-31 07:05:19', '2023-01-31 04:29:34');
