(33212, NULL, 'LXIV', '2023-02-08', '2023-02-08', 'Ordinaria', 'Peticiones', 'Peticiones para gestión', '2023-02-08', NULL, 4, ' EUGENIO JESUS DE LA CRUZ MORALES', NULL, NULL, NULL, NULL, 'user', 'CALLE SANTA CRUZ NUMERO 9\nCOLONIA SAN JOAQUIN,\nCARMEN, CAMPECHE.', 'SOLICITA APOYO PARA COMPRA DE LONAS, AGUA, VINIL PERSONALIZADO PARA UN GRUPO DE BATUCADA.', NULL, 'LIC EUNICE ARELY LOMELIN ESTRADA', 'DIRECTORA DE GESTION SOCIAL', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-02-09 04:25:53', '2023-02-09 07:46:53'),
(33213, NULL, 'LXIV', '2023-02-08', '2023-02-08', 'Ordinaria', 'Correspondencia normal', 'Informes', '2023-01-25', NULL, 1, ' H. CONGRESO DE HIDALGO', NULL, NULL, NULL, NULL, 'user', 'KM. 84.5 CARR. MÉXICO-PACHUCA.\nCENTRO CIVICO C.P. 42080\nPACHUCA DE SOTO, HIDALGO.\n', 'CIRCULAR CELS-LXV/18/2023\nCOMUNICA ELECCION DE INTEGRANTES DE LA DIRECTIVA QUE PRESIDIRÁ LOS TRABAJOS DEL QUINTO PERIODO EXTRAORDINARIO DE SESIONES CORRESPONDIENTE AL PRIMER RECESO DEL SEGUNDO AÑO DE EJERCICIO CONSTITUCIONAL.\nFIRMA: MAESTRO RICO RUIZ, SECRETARIO DE SERVICIOS LEGISLATIVOS.', NULL, 'ING. SONIA ALEJANDRA CASTILLO PERALTA', 'OFICINA DE LA SRIA GRAL', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-02-09 04:57:20', '2023-02-09 02:04:35'),
