(33248, NULL, 'LXIV', '2023-02-10', '2023-02-10', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-02-09', '4228', 7, ' EDUARDO FRANCISCO LUNA MAY', 'SECRETARIO DEL JUZGADO SEGUNDO', 'PODER JUDICIAL DE LA FEDERACION.', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y DE REGIL NUMERO 245, COLONIA SAN RAFAEL, SAN FRANCISCO DE CAMPECHE, CAMPECHE.', 'ACUERDO.\nJUICIO DE AMPARO 79/2023     PROMOVENTE: CONCEPCION PAUL GALLARETA\nAGRÉGUESE A LOS AUTOS EL OFICIO FIRMADO POR EL ENCARGADO DEL DESPACHO DE LA SECRETARIA GENERAL DEL CONGRESO DEL ESTADO DE CAMPECHE CON RESIDENCIA EN ESTA CIUDAD.\nREMÍTASE COPIAS CERTIFICADAS EL PRESENTE JUICIO, ASI COMO ORIGINAL Y COPIA DEL ESCRITO DE AGRAVIOS, EL TRIBUNAL COLEGIADO DEL TRIGÉSIMO PRIMER CIRCUITO CON RESIDENCIA EN ESTA CIUDAD, PARA LA SUSTANCIACION DEL MEDIO DE IMPUGNACION INTERPUESTO, SOLICITÁNDOLE DE LA MANERA MAS ATENTA SE SIRVA ACUSAR  EL RECIBO CORRESPONDIENTE.\nRINDASE EL INFORME, EN EL SENTIDO DE QUE ES CIERTO EL ACTO QUE SE ATRUIBUYE A ESTE ÓRGANO JURISDICCIONAL, CONSISTENTE EN LA EMISION DEL PROVEIDO DE VEINTISIETE DE ENERO DE DOS MIL VEINTITRÉS.\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-02-11 05:25:43', '2023-02-11 07:33:23'),
(33249, NULL, 'LXIV', '2023-02-10', '2023-02-10', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-02-09', '4738', 1, ' EDUARDO FRANCISCO LUNA MAY', 'SECRETARIO DEL JUZGADO SEGUNDO', 'PODER JUDICIAL DE LA FEDERACION.', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y DE REGIL NUMERO 245, COLONIA SAN RAFAEL, SAN FRANCISCO DE CAMPECHE, CAMPECHE.', 'SE COMUNICA EJECUTORIA, SE REQUIERE CUMPLIMIENTO.\nJUICIO DE AMPARO 1068/2022     PROMOVENTE: JOSÉ ARIEL VARGAS ESCOBAR.\nEN CONSECUENCIA, CON FUNDAMENTO EN EL ARTICULO 192 DE LA LEY DE AMPARO, REQUIÉRASE A LA AUTORIDAD RESPONSABLE, PARA QUE DENTRO DEL TÉRMINO DE TRES DIAS, CONTADOS A PARTIR DEL DIA SIGUIENTE AL EN QUE RECIBA EL OFICIO QUE AL EFECTO SE LE GIRA, REMITA LAS CONSTANCIAS CON LAS QUE ACREDITEN HABER DADO CUMPLIMIENTO A LA EJECUTORIA DE AMPARO.\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-02-11 08:23:02', '2023-02-11 06:31:10'),
