(33343, NULL, 'LXIV', '2023-02-24', '2023-02-24', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-02-22', NULL, 2, ' JUZGADO SEGUNDO DE DISTRITO ESTADO DE CAMPECHE', NULL, 'PODER JUDICIAL DE LA FEDERACION', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA DE REGIL N° 245, COLONIA SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE, CAMPECHE.', 'REQUERIMIENTO.\nJUICIO DE AMPARO 106/2023     PROMOVENTE: YOSHIMAR HERNÁNDEZ JIMENES.\n...POR LO TANTO, DE CONFORMIDAD CON EL ARTICULO 9 DE LA LEY DE AMPARO, REQUIÉRASE AL OCURSANTE DE MÉRITO, PARA QUE DENTRO DEL PLAZO DE TRES SIGUIENTES AL EN QUE RECIBA EL OFICIO NOTIFICATORIO, EXHIBA EL DOCUMENTO IDÓNEO CON EL QUE ACREDITE LA REPRESENTACION CON LA QUE SE OSTENTA O MANIFIESTE BAJO PROTESTA DE DECIR VERDAD QUE LA DOCUMENTACIÓN CON LA QUE PRETENDE ACREDITAR SU PERSONALIDAD, ES COPIA FIEL Y EXACTA A SU VERSIÓN IMPRESA.\nFIRMA: KATHERINE CHAVEZ LOZOYA, SECRETARIA.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-02-25 07:30:31', '2023-02-25 04:52:24'),
(33344, NULL, 'LXIV', '2023-02-24', '2023-02-24', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-02-23', NULL, 1, 'C. CRISTIAN JOSÉ AVILA SOSA', 'ACTUARIO JUDICIAL', 'TRIBUNAL COLEGIADO DEL XXXI CIRCUITO P.J.F.', NULL, NULL, 'user', 'CAMPECHE, CAMPECHE.', 'ACUERDO, AMPARO EN REVISION.\nJUICIO DE AMPARO: 1673/2021-V-A    DE CONFORMIDAD CON EL ARTICULO 82 DE LA LEY DE AMPARO, HÁGASE DEL CONOCIMIENTO DE LA CONTRAPARTE DE LA RECURRENTE QUE DENTRO DEL PLAZO DE CINCO DIAS, CONTADOS A PARTIR DEL DIA SIGUIENTE A AQUEL EN QUE SURTA EFECTOS LA NOTIFICACION DE LA ADMISION DEL RECURSO PODRÁ ADHERIRSE A LA REVISION INTERPUESTA DEBIENDO EXPRESAR LOS AGRAVIOS CORRESPONDIENTES, EN LA INTELIGENCIA DE QUE LA ADHESION AL RECURSO SIGUE LA SUERTE PROCESAL DE ÉSTE.\nSE EXHORTA A LAS PARTES A QUE CONTINUEN LA TRAMITACION DEL CASO MEDIANTE EL ESQUEMA \"JUICIO EN LINEA\".', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-02-25 07:12:03', '2023-02-25 04:45:27'),
