(33551, NULL, 'LXIV', '2023-03-21', '2023-03-21', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-06', NULL, 3, 'LIC. JORGE ALFREDO RUIZ BAEZ', 'SECRETARIO DE JUZGADO SEGUNDO', 'PODER JUDICIAL DE LA FEDERACION', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COLONIA SAN RAFAEL\nSAN FRANCISCO DE CAMPECHE, CAMP.\n', 'INICIO.\nINCIDENTE DE SUSPENSION 232/2023    PROMOVENTE: DOUGLAS AURELIO BORGES LOPEZ.\nSE SOLICITA INFORME PREVIO Y SE FIJAN LAS DIEZ HORAS CON VEINTICINCO MINUTOS DEL VEINTISIETE DE MARZO DE DOS MIL VEINTITRES PARA QUE TENGA VERIFICATIVO LA AUDIENCIA INCIDENTAL.      ENVIA ANEXO.', 'DIRIGIDO A LA LXIV LEGISLATURA DEL CONGRESO DEL ESTADO.', 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-22 04:53:34', '2023-03-22 02:33:44'),
(33552, NULL, 'LXIV', '2023-03-21', '2023-03-21', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-17', NULL, 2, ' RICARDO FRAGOSO BECERRA', 'SECRETARIO', 'JUZGADO SEGUNDO DE DISTRITO - CAMPECHE', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y DE REGIL  N° 245, COLONIA SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE, CAMP.', 'DEL CONTENIDO DEL INFORME JUSTIFICADO QUE RINDIO LA AUTORIDAD RESPONSABLE, SECRETARIO GENERAL DEL CONGRESO DEL ESTADO DE CAMPECHE. SE APRECIA QUE ACOMPAÑÓ UNICAMENTE EL OFICIO ANTES CITADO, CON EL QUE DIÓ CONTESTACION A LA PETICION DE CATORCE DE NOVIEMBRE DE 2022, REALIZADA POR EL AQUÍ QUEJOSO, NO OBSTANTE, NO REMITIÓ EL ACUERDO QUE RECAYÓ A LA MISMA.\nREQUIERASE A LA AUTORIDAD RESPONSABLE PARA QUE EN EL TERMINO DE TRES DÍAS REMITA COPIA DEBIDAMENTE CERTIFICADA Y LEGIBLE DEL ACUERDO QUE RECAYÓ A LA PETICIÓN DE 14 DE NOVIEMBRE DE 2022 FORMULADA POR LA PARTE QUEJOSA.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-22 05:33:50', '2023-03-22 02:02:00'),
(33553, NULL, 'LXIV', '2023-03-21', '2023-03-21', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-13', NULL, 2, ' JUZGADO PRIMERO DE DISTRITO DE CENTRO AUXILIAR DE LA 1RA. REGION', 'CIUDAD DE MEXICO.', NULL, NULL, NULL, 'user', NULL, 'ARCHIVO.\nJUICIO DE AMPARO 2963/2019  PROMOVENTE: ANASTACIO OCHOA PACHECO.\nVISTO EL ESTADO PROCESAL QUE GUARDAN LOS AUTOS, SE ADVIERTE QUE EL JUICIO EN QUE SE ACTUA SE ENCUENTRA DEBIDAMENTE INTEGRADO POR ENDE, CON FUNDAMENTE EN EL ARTICULO 214 DE LA LEY DE AMPARO, INTERPRETADO EN SENTIDO CONTRARIO ARCHÍVESE EL ASUNTO COMO CONCLUIDO.\nEL DUPLICADO DEL INCIDENTE DE SUSPENSION ES SUSCEPTIBLE DE DESTRUCCIÓN.\nFIRMA: MARIO PÉREZ ISLAS, SECRETARIO.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-22 06:17:35', '2023-03-22 03:17:23'),
