(33594, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-27', NULL, 2, ' ALEJANDRO QUAN KIU MELGAR', 'SECRETARIO', 'JUZGADO 1° DE DISTRITO EN EL ESTADO', NULL, NULL, 'user', 'AV. PATRICIO RUEBA DE REGIL NUM. 245 COL. SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE.', ' EJECUTORIA.\nEXPEDIENTE 1046/2022-VI-A    QUEJOSO: SELENE DEL ROSARIO HAAS BAC\nVISTA LA CERTIFICACION QUE ANTECEDE, SE ADVIERTE QUE HA TRASCURRIDO EL PLAZO LEGAL DE 10 DIAS, DENTRO DEL QUE LA PARTE QUEJOSA PUDO RECURRIR EN REVISIÓN LA SENTENCIA DE 6 DE DICIEMBRE DE 2022, DICTADA EN ESTE JUICIO DE AMPARO, SIN HABERLO HECHO; POR TANTO, CON FUNDAMENTO EN EL ARTICULO 86 DE LA LEY DE AMPARO, EN RELACION CON LOS DIVERSOS 356, FRACCIÓN II Y 357 DEL CODIGO FEDERAL DE PROCDIMIENTOS CIVILES DE APLICACION SUPLETORIA AL CITADO ORDENAMIENTO LEGAL, SE DECLARA QUE DICHA RESOLUCIÓN HA CAUSADO EJECUTORIA.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-29 02:53:46', '2023-03-29 03:58:11'),
(33595, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'Peticiones', 'Peticiones para gestión', '2023-03-28', NULL, 1, 'DIP CESAR ANDRES GONZALEZ DAVID', 'DIPUTADO PLURINOMINAL MORENA', 'H CONGRESO DEL ESTADO', NULL, NULL, 'user', NULL, 'SOLICITA REUNION CON COMISION DE PROCURACION E IMPARTICION DE JUSTICIA, ASIMISMO CON LA COMISION DE DERECHOS HUMANOS Y ASUNTOS DE FAMILIA DEL H. CONGRESO DEL ESTADO CON EL OBJETIVO DE SOCIALIZAR Y EXTENDER LA INFORMACION DE MANERA DETALLADA EN RELACION A LA INICIATIVA PRESENTADA EL 25 DE NOVIEMBRE DE 2022, PARA QUE EN CONJUNTO CON LA SECRETARIA DE INCLUSION DEL ESTADO DE CAMPECHE Y LA COMISION DE DERECHOS HUMANOS DEL ESTADO DIALOGUEN, AMPLIEN LA INFORMACION Y DICTAMINEN LA INICIATIVA DE REFORMA AL CODIGO CIVIL DEL ESTADO EN LO QUE RESPECTA A LA LEY DE IDENTIDAD DE GENERO.', NULL, 'DIP HECTOR MALAVE GAMBOA', 'DIPUTADO PLURINOMINAL MORENA', 'H CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-29 02:12:28', '2023-03-29 02:48:35'),
(33596, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'Correspondencia normal', 'Informes', '2023-03-21', NULL, NULL, 'LIC. ROSELY ALEJANDRA COCOM COUOH', 'PRESIDENTE', 'JUNTA DE CONCILIACION Y ARBITRAJE', NULL, NULL, 'user', 'AV. LOPEZ PORTILLO NUM 143 ENTRE CALLE LEXMAR Y SAN DIEGO, COL. TEPEYAC C.P. 24090, CAMPECHE, CAMP', 'EXPEDIENTE 119/2022 DIEGO MARTIN GOMEZ LEON VS PODER LEGISLATIVO DEL ESTADO DE CAMPECHE.\nSE DEJA SIN EFECTO UNICA Y EXCLUSIVAMENTE LA FECHA Y HORA SEÑALADA EN EL ACUERDO DE DATA 24 DE NOVIEMBRE DE 2022; Y EN SU LUGAR SE SEÑALA LAS 11:30 HRS. DEL 18 DE ABRIL DEL AÑO 2023 PARA QUE TENGA VERIFICATIVO LA AUDIENCIA DE ARBITRAJE.', NULL, 'L.C. JOSE JAIME PARRES MORENO', 'DIRECTOR DE SERVICIOS ADMINIST', 'H. CONGRESO DEL ESTADO.', NULL, NULL, NULL, 0, '2023-03-29 06:49:23', '2023-03-29 04:44:59'),
(33597, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-24', '10338', 6, 'LIC. EDUARDO ALCOCER DIAZ', 'SECRETARIO', 'JUZGADO SEGUNDO DE DISTRITO - CAMPECHE', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COL. SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE.', 'INICIO\nJUICIO DE AMPARO INDIRECTO 991/2022   PROMOVENTE. ELDA ROSA UC MAY.\nSIN TRAMITARSE EL INCIDENTE DE SUSPENSIÓN, POR NO HABERLO SOLICITADO EXPRESAMENTE LA PARTE QUEJOSA.    SOLICITA INFORME JUSTIFICADO, FIJA FECHA DE AUDIENCIA CONSTITUCIONAL PARA EL 30 DE MARZO A LAS NUEVE HORAS CON VEINTE MINUTOS.\nSOLICITA SE DECLARE LA INCONSTITUCIONALIDAD DEL ARTICULO OCTAVO TRANSITORIO DE LA LEY DE SEGURIDAD Y SERVICIOS SOCIALES DE LOS TRABAJADORES DEL ESTADO DE CAMPECHE, PORQUE RESTRINGE EL DERECHO DEL SERVIDOR PÚBLICO DE DISFRUTAR EL 100 % DEL MONTO QUE COMO PENSION TIENE DERECHO. SOLICITA SEA DECLARADO INCONSTITUCIONAL POR CONTRAVENIR EL ESPIRITU CONSTITUCIONAL DEL ART. 123 APARTADO B, FRACCION XI DE LA CONSTITUCIÓN POLÍTICA FEDERAL. ', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-29 03:00:22', '2023-03-29 05:09:06'),
(33598, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'correspondencia especial', 'Exhortos', '2023-03-24', '9941', 2, 'LIC. EDUARDO ALCOCER DIAZ', 'SECRETARIO', 'JUZGADO SEGUNDO DE DISTRITO - CAMPECHE', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COL. SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE.', 'ACUERDO.\nJUICIO DE AMPARO 841/2022    PROMOVENTE: JENNY DEL CARMEN SOLORZANO SÁNCHEZ Y OLGA MARIA SANCHEZ COHUÓ.\nSE CONCLUYE QUE EL FALLO PROTECTOR HA QUEDADO CUMPLIDO, PUES SE ACATÓ EN SUS TÉRMINOS LA RESOLUCIÓN EN LA QUE SE CONCEDIÓ EL AMPARO Y PROTECCIÓN DE LA JUSTICIA FEDERAL.\nEN MÉRITO DE LO ANTERIOR HÁGASE SABER A LAS PARTES QUE PUEDEN INCORFORMARSE CON ESTA RESOLUCIÓN PARA LO QUE DEBERÁN PRESENTAR SU ESCRITO RESPECTIVO DENTRO DE LOS 15 DIAS HÁBILES SEGUIENTES DE LA NOTIFICACIÓN DE ESTE AUTO.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-29 08:04:03', '2023-03-29 06:04:12'),
(33599, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-13', NULL, 2, ' JUZGADO PRIMERO DE DISTRITO DE CENTRO AUXILIAR DE LA 1RA. REGION', 'CIUDAD DE MEXICO.', NULL, NULL, NULL, 'user', NULL, 'ARCHIVO.\nJUICIO DE AMPARO 3093/2019     PROMOVENTE: MARCELO MARTÍNEZ MICAELO.\nSE DECLARA QUE HA CAUSADO EJECUTORIA, SE DETERMINA QUE EL PRESENTE EXPEDIENTE ES SUSCEPTIBLE DE DESTRUCCIÓN EN UN PLAZO DE TRES AÑOS CONTADO A PARTIR DEL DIA SIGUIENTE AL EN QUE SURTA EFECTOS LA NOTIFICACION DEL   PRESENTE AUTO.    ARCHÍVENSE POR SEPARADO LOS CUADERNOS INCIDENTALES,   EL DUPLICADO DEL INCIDENTE ES SUSCEPTIBLE DE DESTRUCCIÓN EN EL PLAZO DE SEIS MESES.\nFIRMA: SELENE GUADALUPE RAMOS FLORES, SECRETARIA.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-29 07:42:40', '2023-03-29 02:16:35'),
(33600, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-15', NULL, 10, ' JUZGADO PRIMERO DE DISTRITO DE CENTRO AUXILIAR DE LA 1RA. REGION', 'CIUDAD DE MEXICO.', NULL, NULL, NULL, 'user', NULL, 'SENTENCIA.\nJUICIO DE AMPARO 696/2019    PROMOVENTE: ROBERTO RAMÍREZ RUIZ.\nSE RESUELVE: PRIMERO. SE SOBRESEE EN EL JUICIO DE AMAPRO PROMOVIDO POR ROBERTO RAMÍREZ RUIZ Y OTROS RESPECTO A LOS ACTOS Y AUTORIDADES A QUE SE REFIEREN EN LOS CONSIDERANDOS CUARTO Y QUINTO, Y POR LAS RAZONES EXPUESTAS EN EL DIVERSO SEXTO DE ESTA RESOLUCIÓN.\nFIRMA: JESÚS RIVERA GARCÍA, SECRETARIO.\n\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-29 04:36:23', '2023-03-29 03:55:30'),
(33601, NULL, 'LXIV', '2023-03-28', '2023-03-28', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-03-10', NULL, NULL, ' PODER JUDICIAL DE LA FEDERACION', NULL, NULL, NULL, NULL, 'user', NULL, 'INICIO \nJUICIO DE AMPARO 353/2023    PROMOVENTE NUEVA WAL-MART DE MEXICO S. DE R. L. DE C.V.\nNO ORDENA APERTURA DEL INCIDENTE DE SUSPENSION POR NO HABERLO SOLICITADO LA PARTE QUEJOSA, FIJA FECHA DE AUDIENCIA CONSTITUCIONAL PARA EL 11 DE ABRIL A LAS 12:00 HORAS.\nACTO RECLAMADO EL COBRO DEL MONTO POR CONCEPTO DE DERECHO DE ALUMBRADO PUBLICO.\nENVIA ANEXO.     FIRMA: DAVID ANTONIO GALINDO ARENAS, SECRETARIO.\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-03-29 05:43:26', '2023-03-29 06:13:07');
