(34227, NULL, 'LXIV', '2023-06-23', '2023-06-23', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-06-21', NULL, 2, 'LIC JOSE ABELARDO RODRIGUEZ CANTU', 'SRIO DEL JUZGADO 1°  DISTRITO', 'CAMPECHE', NULL, NULL, 'user', NULL, 'ACUERDO.\nJUICIO DE AMPARO 766/2023-III-A     PROMOVENTE. JONHAIRO ALAIN MENA JIMENEZ.\nCOMUNICA ADMISION DE DEMANDA DE AMPARO, SOLICITA INFORME JUSTIFICADO Y FIJA FECHA DE AUDIENCIA CONSTITUCIONAL PARA EL TREINTA Y UNO DE JULIO A LAS DIEZ HORAS.\nRECLAMA AL CONGRESO DEL ESTADO DE CAMPECHE:  LA OMISION DE CONSIDERAR UN PLAZO CONSIDERABLE PARA LA ADMISION DE UN RECURSO DE REVISION POR PARTE DEL ORGANO GARANTE LOCAL DE TRANSPARENCIA, ESTO EN LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA DEL ESTADO DE CAMPECHE.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-24 06:05:51', '2023-06-24 05:09:17'),
(34228, NULL, 'LXIV', '2023-06-23', '2023-06-23', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-06-21', NULL, 2, 'LIC JOSE ABELARDO RODRIGUEZ CANTU', 'SRIO DEL JUZGADO 1°  DISTRITO', 'CAMPECHE', NULL, NULL, 'user', NULL, 'INICIO.      JUICIO DE AMPARO 766/2023-IV-A    PROMOVENTE:  JONHAIRO ALAIN MENA JIMÉNEZ.\nSOLICITA INFORME PREVIO, FIJA FECHA DE AUDIENCIA INCIDENTAL PARA EL VEINTIOCHO DE JUNIO A LAS NUEVE HORAS CON DIEZ MINUTOS.\nRECLAMA AL CONGRESO DEL ESTADO DE CAMPECHE:  LA OMISION DE CONSIDERAR UN PLAZO CONSIDERABLE PARA LA ADMISION DE UN RECURSO DE REVISION POR PARTE DEL ORGANO GARANTE LOCAL DE TRANSPARENCIA, ESTO EN LA LEY DE TRANSPARENCIA Y ACCESO A LA INFORMACIÓN PÚBLICA DEL ESTADO DE CAMPECHE.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-24 05:03:44', '2023-06-24 02:40:37'),
(34229, NULL, 'LXIV', '2023-06-23', '2023-06-23', 'Ordinaria', 'Peticiones', 'Peticiones para gestión', '2023-06-23', NULL, 4, ' CLARA HERNANDEZ GRAJALES', NULL, NULL, NULL, NULL, 'user', 'CALLE DELICIAS NUMERO 11\nCOL. LOMAS DEL SURESTE C.P. 24060\nCAMPECHE, CAMP.', 'SOLICITA APOYO PARA ESTUDIO MÉDICO. - RESONANCIA MAGNÉTICA SIMPLE-.\nANEXA ORDEN MÉDICA.', NULL, 'LIC EUNICE ARELY LOMELIN ESTRADA', 'DIRECTORA DE GESTION SOCIAL', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-24 07:07:44', '2023-06-24 02:20:50'),
(34230, NULL, 'LXIV', '2023-06-23', '2023-06-23', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-06-20', NULL, 2, ' JUZGADO SEGUNDO DISTRITO DEL CENTRO AUXILIAR DE LA PRIMERA REGION CON', 'EN LA CIUDAD DE MEXICO', 'SEDE DEL PODER JUDICIAL DE LA FEDERACION', NULL, NULL, 'user', 'EDUARDO MOLINA NUM 1 PLAZA DEL PARQUE CIUDAD DE MEXICO', 'ACUERDO.       INCIDENTE DE SUSPENSION 3316/2019     PROMOVENTE: OSCAR RODRIGUEZ ALVAREZ.\nAGRÉGUESE A LOS AUTOS EL OFICIO REMITIDO POR EL CUARTO TRIBUNAL COLEGIADO DE CIRCUITO DEL CENTRO AUXILIAR DE LA PRIMERA REGION, CON RESIDENCIA EN LA CIUDAD DE MEXICO POR EL QUE REMITE TESTIMONIO DE LA RESOLUCION EMITIDA EN SESION ORDINARIA VIRTUAL DE TREINTA Y UNO DE MAYO DE DOS MIL VEINTITRES, EN EL INCIDENTE EN REVISION 56/2023 DE SU ESTADISTICA Y EL CUADERNO ORIGINAL DEL INCIDENTE DE SUSPENSION EN DOS TOMOS, ACÚSESE DE RECIBO VIA INTERCONEXIÓN.\nFIRMA OFICIO: LIC. LUIS ALBERO PALMA OSORIO, SECRETARIO.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-24 02:12:14', '2023-06-24 06:48:07'),
(34231, NULL, 'LXIV', '2023-06-23', '2023-06-23', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-06-13', NULL, 7, ' TERCER TRIBUNAL COLEGIADO EN  MATERIA ADMINISTRATIVA DEL 2DO. CIRCUIT', NULL, NULL, NULL, NULL, 'user', NULL, 'ACUERDO.\nEXPEDIENTE DE ORIGEN 81/2021   PROMOVENTE DEL PRESENTE ASUNTO. SECRETARIO DE GOBIERNO DEL ESTADO DE SONORA.\nCOMUNICA ADMISION DE RECURSO DE REVISION QUE INTERPONE EL JEFE DE DEPARTAMENTO DE LO CONTENCIOSO DE LA CONSEJERIA JURIDICA DEL GOBIERNO DEL ESTADO DE SONORA, EN CONTRA DE LA SENTENCIA DE VEINTITRÉS DE MARZO DE DOS MIL VEINTIDOS, DICTADA EN EL JUICIO DE AMPARO INDIRECTO 81/2021-VIII POR EL JUEZ DECIMOQUINTO DE DISTRITO EN EL ESTADO DE MÉXICO, CON RESIDENCIA EN NAUCALPAN DE JUÁREZ.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-24 03:55:20', '2023-06-24 02:35:00'),
(34232, NULL, 'LXIV', '2023-06-23', '2023-06-23', 'Ordinaria', 'Peticiones', 'Peticiones para gestión', '2023-06-23', NULL, 2, 'DIP RICARDO MIGUEL MEDINA FARFAN', 'DIPUTADO PLURINOMINAL PRI', 'H CONGRESO DEL ESTADO', NULL, NULL, 'user', NULL, 'SOLICITA FORMALMENTE SE SIRVA CONVOCAR A PARLAMENTO ABIERTO Y SE ORGANICE POR ESTE H. CONGRESO DEL ESTADO, FOROS DE CONSULTA SOBRE LA INICIATIVA PRESENTADA POR EL EJECUTIVO ESTATAL EN MATERIA DE MOVILIDAD Y SEGURIDAD VIAL DEL ESTADO DE CAMPECHE.\nDIRIGIDO TAMBIÉN A LAS COMISIONES DE DERECHOS HUMANOS Y ASUNTOS DE FAMILIA;  DE GOBERNACION Y PROTECCION CIVIL    Y    ESPECIAL DE MOVILIDAD.', NULL, 'LIC. RENÉ AUGUSTO SOSA ENRÍQUEZ', 'ENCARGADO DE DESPACHO DE LA', 'SECRETARIA GENERAL POR MINISTERIO DE LEY.', NULL, NULL, NULL, 0, '2023-06-24 07:52:06', '2023-06-24 04:43:32'),
(34233, NULL, 'LXIV', '2023-06-26', '2023-06-26', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-06-26', '20357', 2, 'LIC. JORGE ALFREDO RUIZ BAEZ', 'SECRETARIO DE JUZGADO SEGUNDO', 'PODER JUDICIAL DE LA FEDERACION', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COLONIA SAN RAFAEL\nSAN FRANCISCO DE CAMPECHE, CAMP.\n', 'EJECUTORIA.      JUICIO DE AMPARO 500/2022     PROMOVENTE: BUENAVENTURA GRUPO PECUARIO, SOCIEDAD ANONIMA DE CAPITAL VARIABLE.\nVISTO EL ESTADO QUE GUARDAN LOS PRESENTES AUTOS Y LA CERTIFICACION QUE ANTECEDE, SE ADVIERTE QUE HA TRANSCURRIDO EL PLAZO SIN QUE SE HUBIESE RECURRIDO LA SENTENCIA, SE DECLARA QUE HA CAUSADO EJECUTORIA: PRACTIQUENSE LOS APUNTES EN EL LIBRO DE GOBIERNO.\n\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-27 06:27:05', '2023-06-27 07:19:03'),
(34234, NULL, 'LXIV', '2023-06-26', '2023-06-26', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-06-22', '20663', 2, 'LIC. EDUARDO ALCOCER DIAZ', 'SECRETARIO', 'JUZGADO SEGUNDO DE DISTRITO - CAMPECHE', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COL. SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE.', 'CAUSA ESTADO CALIFICACION DE CUMPLIMIENTO.\nJUICIO DE AMPARO INDIRECTO 841/2022   PROMOVENTE: JENNY DEL CARMEN SOLORZANO SANCHEZ Y OLGA MARIA SANCHEZ COHUÓ.\nVISTA LA CERTIFICACION DE CUENTA, SE ADVIERTE QUE HA TRANSCURRIDO EL PLAZO SEÑALADO PARA INTERPONER RECURSO DE INCONFORMIDAD, SE DECLARA QUE HA CAUSADO ESTADO Y SE TIENE POR CONSENTIDA LA CALIFICACIÓN QUE ESTE ÓRGANO JURISDICCIONAL DETERMINÓ RESPECTO AL CUMPLIMIENTO DE LA EJECUTORIA DE AMPARO.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-27 06:37:38', '2023-06-27 05:40:37'),
(34235, NULL, 'LXIV', '2023-06-26', '2023-06-26', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-06-23', NULL, 2, ' PODER JUDICIAL DE LA FEDERACION', NULL, NULL, NULL, NULL, 'user', NULL, 'ACUERDO.     JUCIO DE AMPARO 766/2023     PROMOVENTE: JONHAIRO ALAIN MENA JIMENEZ.\nAGREGUESE A LO DE CUENTA, CON LO QUE LA AUTORIDAD REMITE DIGITALIZACIÓN DE CONSTANCIAS CONDUCENTES DEL INCIDENTE DE SUSPENSION EN EL JUICIO DE AMPARO INDIRECTO 766/2023, ENTRE LAS QUE SE ENCUENTRA EL INFORME MATERIA DE LA QUEJA Y EL ESCRITO DE JONHAIRO ALAIN MENA JIMÉNEZ, CON EL QUE INTRPONE RECURSO DE QUEJA Y EXPRESA AGRAVIOS, CONTRA EL ACUERDO DE VEINTIUNO DE JUNIO DE DOS MIL VEINTITRES, DICTADO EN EL INCIDENTE DE SUSPENSIÓN EN EL JUICIO DE AMPARO INDIRECTO 766/2023 EL QUE SE NEGÓ LA SUSPENSIÓN PROVISIONAL. INFÓRMESE SU RECEPCIÓN.\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-06-27 03:35:38', '2023-06-27 04:27:45'),
