(34785, NULL, 'LXIV', '2023-09-14', '2023-09-14', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-09-11', NULL, 13, 'LIC. JORGE ALFREDO RUIZ BAEZ', 'SECRETARIO DE JUZGADO SEGUNDO', 'PODER JUDICIAL DE LA FEDERACION', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COLONIA SAN RAFAEL\nSAN FRANCISCO DE CAMPECHE, CAMP.\n', 'ADMISION DE DEMANDA.    JUICIO DE AMPARO 1132/2023      PROMOVENTE.  ALFONSO ALEJANDRO DURAN REYES EN SU CARACTER DE DIRECTOR GENERAL DE AUNTOS JURIDICOS Y TRANSPARENCIA DEL AYUNTAMIENTO DEL MUNICIPIO DE CAMPECHE.\nSE ADMITE A TRÁMITE LA DEMANDA DE AMPARO.   SOLICITA INFORME JUSTIFICADO Y FIJA FECHA DE AUDIENCIA CONSTITUCIONAL PARA EL VEINTISEIS DE OCTUBRE DE DOS MIL VEINTITRÉS A LAS ONCE HORAS CON CUARENTA MINUTOS.\nASUNTO: SE REMITE SEPARACION DE JUICIOS.    RECLAMA DEL CONGRESO DEL ESTADO DE CAMPECHE: LA EJECUCION DE LO ORDENADO DENTRO DEL CUARTO ACUERDO DE INCUMPLIMIENTO DE RESOLUCION DE DIVERSOS RECURSOS DE REVISION, CONSISTENTE EN DAR INICIO AL JUICIO POLITICO CUYO PROCEDIMIENTO SE ORDENA CULMINE EN LA SEPARACION DEL CARGO DE SERVIDOR PÚBLICO Y EL FINCAMIENTO DE RESPONSABILIDADES ADMINISTRATIVAS Y PARA EMITIR LA DECLARATORIA DE PROCEDENCIA.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-09-15 06:26:16', '2023-09-15 06:59:54'),
(34786, NULL, 'LXIV', '2023-09-14', '2023-09-14', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-09-11', NULL, 6, 'LIC. JORGE ALFREDO RUIZ BAEZ', 'SECRETARIO DE JUZGADO SEGUNDO', 'PODER JUDICIAL DE LA FEDERACION', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y REGIL N° 245, COLONIA SAN RAFAEL\nSAN FRANCISCO DE CAMPECHE, CAMP.\n', 'SUSPENSION PROVISIONAL. JUICIO DE AMPARO 1132/2023      PROMOVENTE.  ALFONSO ALEJANDRO DURAN REYES EN SU CARACTER DE DIRECTOR GENERAL DE AUNTOS JURIDICOS Y TRANSPARENCIA DEL AYUNTAMIENTO DEL MUNICIPIO DE CAMPECHE.\nSE CONCEDE LA SUSPENSION PROVISIONAL PARA EL ÚNICO EFECTO DE QUE NO SE HAGA EFECTIVO EL COBRO D ELA MULTA IMPUESTA A LA AQUI PERSONA OFICIAL QUEJOSA, HASTA EN TANTO SE COMUNICQUE A LA RESPONSABLE, LO QUE EN SU TIEMPO SE RESUELVA SOBRE LA SUSPENSION DEFINITIVA.   SOLICITA INFORME PREVIO Y FIJA FECHA DE AUDIENCIA INCIDENTAL PARA EL VEINTE DE SEPTIEMBRE DE DOS MIL VEINTITRÉS A LAS DIEZ HORAS CON CUARENTA Y CINCO MINUTOS.\nENVIA ANEXO COPIA SIMPLE DE LA DEMANDA DE AMPARO.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-09-15 05:10:06', '2023-09-15 06:03:12'),
(34787, NULL, 'LXIV', '2023-09-14', '2023-09-14', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-09-11', '28464', 10, ' MAYRA GRISELLY PECH IUIT', 'SECRETARIA', 'JUZGADO SEGUNDO DE DISTRITO - CAMPECHE', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y DE REGIL N° 245, COL SAN RAFAEL\nSAN FRANCISCO DE CAMPECHE, CAMPECHE.', 'ADMISION DE DEMANDA.    JUICIO DE AMPARO INDIRECTO 1133/2023      PROMOVENTE.   MIGUEL ANGEL TORAYA PONCE EN SU CARACTER DE  TITULAR DE LA UNIDAD DE TRANSPARENCIA Y ARCHIVOS DEL  MUNICIPIO DE CAMPECHE\nSE ADMITE A TRÁMITE LA DEMANDA DE AMPARO Y SOLICITA INFORME JUSTIFICADO Y FIJA FECHA DE AUDIENCIA CONSTITUCIONAL PARA EL VEINTISIETE DE OCTUBRE DE DOS MIL VEINTITRÉS A LAS DIEZ HORAS CON VEINTE MINUTOS.\nEN CONSECUENCA SE DECRETA DE PLANO Y DE OFICIO LA SEPARACION DE JUICIOS EN EL PRESENTE ASUNTO DE CONFORMIDAD CON EL ÚLTIMO PÁRRAFO DEL ARTICULO 2 DE LA LEY DE AMPARO Y DIVERSOS 71, 72, 73, 75 Y 76 DEL CODIGO FEDERAL DE PROCEDIMIENTOS CIVILES, APLICADOS EN SENTIDO CONTRARIO.\n  RECLAMA DEL CONGRESO DEL ESTADO DE CAMPECHE: LA EJECUCION DE LO ORDENADO DENTRO DE LOS TRES ACUERDOS DE INCUMPLIMIENTO DE RESOLUCION DE DIVERSOS RECURSOS DE REVISION, CONSISTENTE EN DAR INICIO AL JUICIO POLITICO CUYO PROCEDIMIENTO SE ORDENA CULMINE EN LA SEPARACION DEL CARGO DE SERVIDOR PÚBLICO Y EL FINCAMIENTO DE RESPONSABILIDADES ADMINISTRATIVAS Y PARA EMITIR LA DECLARATORIA DE PROCEDENCIA.\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-09-15 07:14:39', '2023-09-15 04:36:43'),
(34788, NULL, 'LXIV', '2023-09-14', '2023-09-14', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-09-11', '28378', 6, ' MAYRA GRISELLY PECH IUIT', 'SECRETARIA', 'JUZGADO SEGUNDO DE DISTRITO - CAMPECHE', NULL, NULL, 'user', 'AV. PATRICIO TRUEBA Y DE REGIL N° 245, COL SAN RAFAEL\nSAN FRANCISCO DE CAMPECHE, CAMPECHE.', 'SUSPENSION PROVISIONAL. JUICIO DE AMPARO 1133/2023      PROMOVENTE.  MIGUEL ANGEL TORAYA PONCE EN SU CARACTER DE  TITULAR DE LA UNIDAD DE TRANSPARENCIA Y ARCHIVOS DEL  MUNICIPIO DE CAMPECHE.\nSE CONCEDE LA SUSPENSION PROVISIONAL PARA EL ÚNICO EFECTO DE QUE NO SE HAGA EFECTIVO EL COBRO DE LA MULTA HASTA EN TANTO SE COMUNIQUE A LA AUTORIDAD RESPONSABLE LA SENTENCIA DE AMPARO EJECUTORIA QUE SE DICTE EN EL EXPEDIENTE PRINCIPAL.  \nSOLICITA INFORME PREVIO Y FIJA FECHA DE AUDIENCIA INCIDENTAL PARA EL VEINTIUNO DE SEPTIEMBRE DE DOS MIL VEINTITRÉS A LAS DIEZ HORAS CON  CINCO MINUTOS.\nENVIA ANEXO COPIA SIMPLE DE LA DEMANDA DE AMPARO.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-09-15 07:35:04', '2023-09-15 03:32:08'),
