(34862, NULL, 'LXIV', '2023-09-21', '2023-09-21', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-09-19', NULL, 4, ' ALEJANDRO QUAN KIU MELGAR', 'SECRETARIO', 'JUZGADO 1° DE DISTRITO EN EL ESTADO', NULL, NULL, 'user', 'AV. PATRICIO RUEBA DE REGIL NUM. 245 COL. SAN RAFAEL.\nSAN FRANCISCO DE CAMPECHE.', 'INFORME PREVIO.    INCIDENTE EN SUSPENSION 1119/2023-IV-A  PROMOVENTE: HÉCTOR MANUEL BORGES RODRIGUEZ EN REPRESENTACION DE LOS QUEJOSOS.\nCOMUNICA ACUERDO Y REENVIA OFICIO.   SOLICITA INFORME PREVIO Y FIJA FECHA DE AUDIENCIA INCIDENTAL CON FECHA  VEINTE DE SEPTIEMBRE DE DOS MIL VEINTITRES A LAS NUEVE HORAS CON QUINCE MINUTOS.\nRECLAMA LA APROBACION DEL DECRETO 250 POR EL QUE SE EXPIDE LA LEY DE MOVILIDAD Y SEGURIDAD VIAL DEL ESTADO DE CAMPECHE, ASÍ COMO LA PUBLICACION EN EL PERIODICO OFICIAL DE LA LEY MENCIONADA.  \nENVIA ANEXO.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-09-22 05:00:04', '2023-09-22 04:45:00'),
(34863, NULL, 'LXIV', '2023-09-21', '2023-09-21', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-09-20', NULL, 4, 'LIC JOSE ABELARDO RODRIGUEZ CANTU', 'SRIO DEL JUZGADO 1°  DISTRITO', 'CAMPECHE', NULL, NULL, 'user', NULL, 'INORME PREVIO.     JUICIO DE AMPARO 1164/2023      PROMOVENTE. ALFONSO ALEJANDRO DURAN REYES.\nSOLICITA INFORME PREVIO Y FIJA FECHA DE AUDIENCIA INCIDENTAL  PARA EL VEINTISIETE DE SEPTIEMBRE DE DOS MIL VEINTITRES  A LAS NUEVE HORAS.\nSE CONCEDE LA SUSPENSION PROVISIONAL PARA QUE DE NO HABERSE EFECTUADO EL COBRO DE LA MULTA IMPUESTA A LA QUEJOSA, EN PROVEIDO DE QUINCE DE AGOSTO DE DOS MIL VEINTITRÉS, LA AUTORIDAD RESPONSABLE SE ABSTENGA A REALIZAR EL COBRO, HASTA EN TANTO SE NOTIFIQUE LA INTERLOCUTORIA QUE RESUELVA SOBRE LA SUSPENSION DEFINITIVA.\nENVIA ANEXO.\n', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-09-22 04:23:41', '2023-09-22 06:13:41');
