(35285, NULL, 'LXIV', '2023-11-17', '2023-11-17', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-10-31', NULL, 1, ' JUZGADO TERCERO DE DISTRITO CAMPECHE', NULL, 'PODER JUDICIAL DE LA FEDERACION.', NULL, NULL, 'user', NULL, 'SENTENCIA, TERMINOS DE ACUERDO A LA LEY DE AMPARO.      JUICIO DE AMPARO 222/2023-IV     \nSE RESUELVE: PRIMERO. SE SOBRESEE EN EL JUICIO DE AMPARO PROMOVIDO POR ROGER RUBEN ROSARIO PÉREZ CONTRA LOS ACTOS Y AUTORIDADES PRECISADOS EN EL CONSIDERANDO TERCERO, POR LOS MOTIVOS EXPUESTOS EN DICHO CONSIDERANDO.\nSEGUNDO. LA JUSTICIA DE LA UNION AMPARA Y PROTEGE A ROGER RUBEN ROSARIO PÉREZ, EN CONTRA DE LOS ACTOS Y AUTORIDADES PRECISADOS EN EL CONSIDERANDO CUARTO, POR LOS MOTIVOS Y PARA LOS EFECTOS SEÑALADOS EN EL CONSIDERANDO SEPTIMO Y OCTAVO DE ESTA SENTENCIA.\nTERCERO. INTÉGRESE AL SISTEMA INTEGRAL DE SEGUIMIENTO DE EXPEDIENTES LA VERSION PÚBLICA DE ESTA SENTENCIA, EN LOS TÉRMINOS SEÑALADOS EN EL CONSIDERANDO DÉCIMO DE ESTA SENTENCIA.\nFIRMA: MARICELA CORTEZ PORFIRIO, SECRETARIA.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-11-18 02:46:15', '2023-11-18 05:38:38'),
(35286, NULL, 'LXIV', '2023-11-17', '2023-11-17', 'Ordinaria', 'correspondencia especial', 'Juicios de amparos', '2023-11-09', NULL, 1, ' JUZGADO TERCERO DE DISTRITO CAMPECHE', NULL, 'PODER JUDICIAL DE LA FEDERACION.', NULL, NULL, 'user', NULL, 'SENTENCIA.    JUICIO DE AMPARO 182/2022-I, \nSE DECLARA CUMPLIDA SIN EXCESO NI DEFECTO LA SENTENCIA DICTADA EN ESTE JUICIO DE AMPARO.\nSE RESERVA PROVEER EL ARCHIVO HASTA EN TANTO TRANSCURRA EL PLAZO DE 15 DIAS CON EL QUE CUENTA LA PARTE QUEJOSA PARA INTERPONER RECURSO DE AMPARO.\nFIRMA: MARICELA CORTEZ PORFIRIO, SECRETARIA.', NULL, 'LIC. MARITZA ARCOS CRUZ', 'CONTROL DE PROCESOS LEGISLATIV', 'H. CONGRESO DEL ESTADO', NULL, NULL, NULL, 0, '2023-11-18 05:29:25', '2023-11-18 05:04:52'),
